// Package bench benchmarks the PEGO backends against each other and against Go standard library parsers.
// Results are recorded in docs/benchmarks.md.
//
//	go test ./bench -bench . -benchmem
//
// gen/ holds parsers generated by pego gen; regenerate them with go generate ./bench.
package bench

